<?php get_header();the_post();$terms=get_the_terms(get_the_ID(),'orh_service_group');$thumb=orh_media_url(get_the_ID(),'large');?><main class="service-single"><div class="service-single-head"><div><div class="eyebrow">УСЛУГА ПРОДЮСЕРСКОГО ЦЕНТРА</div><h1><?php the_title();?></h1><?php if($terms&&!is_wp_error($terms)):?><div class="service-tags"><?php foreach($terms as $t)echo '<a href="'.esc_url(get_term_link($t)).'">'.esc_html($t->name).'</a>';?></div><?php endif;?></div><?php if($thumb):?><div class="service-hero-image" style="background-image:url('<?php echo esc_url($thumb);?>')"></div><?php endif;?></div><div class="service-single-body"><article><?php the_content();?></article><aside><b>Хотите продвинуть свою песню?</b><p>Оставьте заявку, и мы расскажем о формате услуги, вариантах размещения и условиях.</p><a class="primary wide" href="<?php echo esc_url(home_url('/artist-application/'));?>">Оставить заявку →</a><?php if($terms&&!is_wp_error($terms)&&!empty($terms[0])):?><a class="service-back" href="<?php echo esc_url(get_term_link($terms[0]));?>">← Все услуги направления</a><?php endif;?></aside></div></main><?php get_footer();?>